import { Meta, StoryObj } from "@storybook/react";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { PropsWithChildren } from "react";
import { ProductCard } from "@/core/components/modules/product-card/product-card";
import { Primary as ProductCardPrimaryStory } from "@/core/components/modules/product-card/product-card.stories";
import { ShakeConfig, useShakeable } from "./use-shakeable";
import { desktopOnlyMode } from "../../../.storybook/preview";

const ShakeableStory = ({ children, ...shakeConfig }: PropsWithChildren<ShakeConfig>) => {
  const [Shakeable, shake] = useShakeable(shakeConfig);

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "2rem", margin: "2rem" }}>
      <Shakeable>{children}</Shakeable>

      <PrimaryButton label="Press to shake!" onClick={shake} />
    </div>
  );
};

const meta = {
  title: "Foundation/Shakeable",
  component: ShakeableStory,
  parameters: {
    chromatic: desktopOnlyMode,
  },
} satisfies Meta<typeof ShakeableStory>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Primary: Story = {
  args: {
    rotationDegrees: 5,
    shakesPerRepeat: 10,
    durationPerRepeat: 5000,
    repeat: 1,
    repeatDelay: 1000,
    children: <PrimaryButton label={"I'm shaking!"} />,
  },
};

export const ProductCardShaken: Story = {
  args: {
    ...Primary.args,
    children: <ProductCard {...ProductCardPrimaryStory.args} />,
  },
};
